44	// EnableOptions holds the flags for `entire enable`.
45	type EnableOptions struct {
46		LocalDev            bool
47		UseLocalSettings    bool
48		UseProjectSettings  bool
49		ForceHooks          bool
50		SkipPushSessions    bool
51		CheckpointRemote    string
52		Telemetry           bool
53		AbsoluteGitHookPath bool
54	}
