80	func hasStrategyFlags(cmd *cobra.Command) bool {
81		return cmd.Flags().Changed(flagCheckpointRemote) || cmd.Flags().Changed(flagSkipPushSessions)
82	}
83	
84	func hasSummaryProviderFlags(cmd *cobra.Command) bool {
85		return cmd.Flags().Changed(flagSummarizeAgent) || cmd.Flags().Changed(flagSummarizeModel)
86	}
