228	func saveSettingsToTarget(ctx context.Context, s *EntireSettings, targetFile string) error {
229		switch targetFile {
230		case settings.EntireSettingsLocalFile:
231			return SaveEntireSettingsLocal(ctx, s)
232		case settings.EntireSettingsFile:
233			return SaveEntireSettings(ctx, s)
234		default:
235			return fmt.Errorf("unknown settings target %q", targetFile)
236		}
237	}
