	t.Helper()

	pathDir := t.TempDir()
	for _, name := range []string{"git", "sh"} {
		if err := preserveToolOnPath(name, pathDir); err != nil {
			t.Fatalf("preserve %s on PATH: %v", name, err)
		}
	}

	t.Setenv("PATH", pathDir)
}

